function loop(now){uiDue=now-lastUiTime>=100;if(uiDue)lastUiTime=now;const dt=Math.min(.04,(now-last)/1000);last=now;update(dt);updateCamera(dt);updateAmbience();drawScene(now);drawRegionalWeather(now);if(uiDue){drawRadar();updateGroundUI();}requestAnimationFrame(loop)}

let clueLookTarget=null;
function recordMarkup(r){return `<article class="record-page"><small>${escapeStoryText(r.type)}</small><h2>${escapeStoryText(r.title)}</h2><p>${escapeStoryText(r.text??r.snippet)}</p>${r.clue?`<div class="new-hint">${escapeStoryText(r.clue)}</div>`:''}</article>`;}
function investigate(){
  if(acrobatics.active||pausedByRecord||!running)return;
  const groundPoint=walker.active?nearestStoryPoint(walker,activeStorySite()):null;
  if(walker.active&&!groundPoint)return;
  if(!walker.active&&nearArea?.exploration){if(landing.phase==='landed')toggleGroundWalk();else requestAutoLanding();return;}
  const targetArea=walker.active?landing.site:nearArea;
  if(!targetArea||targetArea.id==='entry'&&!groundPoint)return;
  triggerDragonReaction({...targetArea,y:flight.y},'record');pausedByRecord=true;visited.add(targetArea.id);
  const records=(groundPoint?.recordIds||targetArea.recordIds||[]).map(id=>recordById.get(id)).filter(Boolean);
  records.forEach(r=>collected.add(r.id));if(groundPoint?.observation)observed.add(groundPoint.id);
  $('#recordPlace').textContent=targetArea.name+(groundPoint?' / '+groundPoint.label:'');
  $('#recordPages').innerHTML=records.length?records.map(recordMarkup).join(''):recordMarkup({type:groundPoint?.observation?.type||'環境痕跡',title:groundPoint?.label||targetArea.name,text:groundPoint?.observation?.text||targetArea.historicalRole});
  $('#newHint').textContent=pointClue(groundPoint,records,targetArea,pkg.storyModel.hintLinks,visited)+(collected.size===recordTotal?'\n\nすべての記録が揃った。図書館で、この地域の物語を読める。':'');
  if(collected.size!==recordTotal&&groundPoint?.recordIds.length&&!records.some(r=>r.fieldClue)&&!targetArea.recordIds.every(id=>collected.has(id)))$('#newHint').textContent='';
  const lookId=groundPoint?.lookTargetId||records.find(r=>r.hintTargetId)?.hintTargetId;
  clueLookTarget=areas.find(a=>a.id===lookId)||null;
  $('#lookFromClue').hidden=!clueLookTarget;
  clearMovement();persist();updateHud();$('#recordDialog').showModal();
}
function openJournal(){
  if(!running||pausedByRecord||acrobatics.active)return;
  const entries=journalEntries(pkg.records,collected,storySites,observed);
  const leads=explorationLeads(pkg,collected,observed);
  $('#journalLeads').innerHTML=leads.length?'<h2>今、気になること</h2><p class="lead-intro">拾った言葉から生まれた行き先。気になるものから辿ろう。</p>'+leads.map(lead=>`<article class="lead-card"><h3>${escapeStoryText(lead.title)}</h3><p>${escapeStoryText(lead.clue)}</p></article>`).join(''):entries.length?'<p class="lead-intro">今ある手がかりは調べ終えた。手帳の記録を読み返すか、図書館で旅を振り返ろう。</p>':'';
  $('#journalPages').innerHTML=entries.length?entries.map(recordMarkup).join(''):'<p class="journal-empty">手帳はまだ白紙。折れた観測塔の風布の下に、観測士の記録室がある。</p>';
  clearMovement();pausedByRecord=true;$('#journalDialog').showModal();
}
function closeJournal(){$('#journalDialog').close();}

function closeRecord(){$('#recordDialog').close();pausedByRecord=false;running=true}

addEventListener('keydown',e=>{if(e.target?.matches('input,textarea,select')||document.querySelector('dialog[open]'))return;const k=e.key.toLowerCase();if(k==='escape'){acrobatics.menuOpen=false;$('#settingsPanel').hidden=true;$('#toggleSettings').setAttribute('aria-expanded','false');updateRollUI();return}if(k==='r'||k==='l'||k==='b'||k==='f'||k==='t'){e.preventDefault();if(!e.repeat)requestRoll(k==='t'?'turn':k==='f'?'fall':k==='b'?'dash':k==='l'?'loop':'roll');return}if(acrobatics.active&&['w','a','s','d',' ','q','g','e'].includes(k)){e.preventDefault();return}if(k==='g'){e.preventDefault();if(!e.repeat)toggleGroundWalk();return}if(walker.active&&e.key.startsWith('Arrow')){e.preventDefault();if(e.key==='ArrowLeft')walker.yaw-=.08;if(e.key==='ArrowRight')walker.yaw+=.08;if(e.key==='ArrowUp')walker.pitch=Math.min(1.2,walker.pitch+.06);if(e.key==='ArrowDown')walker.pitch=Math.max(-1.2,walker.pitch-.06);return}if(k==='e'){investigate();return}if(k==='s'&&requestAutoLanding()){e.preventDefault();return}if(['w','a','s','d',' ','q'].includes(k)){keys.add(k);e.preventDefault()}if(e.key==='ArrowLeft')view.yaw-=.08;if(e.key==='ArrowRight')view.yaw+=.08;if(e.key==='ArrowUp')view.height=Math.min(.9,view.height+.06);if(e.key==='ArrowDown')view.height=Math.max(-.45,view.height-.06)});
addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));const cameraPointers=new Map();let pinch=null,pinchUsed=false;
function pointerSpan(){const [a,b]=[...cameraPointers.values()];return a&&b?Math.hypot(a.x-b.x,a.y-b.y):0}
function clearCameraGesture(){cameraPointers.clear();pinch=null;pinchUsed=false;drag=null}
canvas.addEventListener('pointerdown',e=>{
  if(!running||pausedByRecord||e.button>0)return;e.preventDefault();cameraPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});try{canvas.setPointerCapture(e.pointerId)}catch{}
  if(cameraPointers.size===1){drag={x:e.clientX,y:e.clientY};pinchUsed=false}
  else{drag=null;pinchUsed=true;if(cameraPointers.size===2&&!walker.active)pinch={span:Math.max(1,pointerSpan()),distance:cameraDistance}}
});
canvas.addEventListener('pointermove',e=>{
  if(!cameraPointers.has(e.pointerId))return;e.preventDefault();cameraPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
  if(cameraPointers.size>1){if(pinch&&!walker.active)setCameraDistance((pinch.distance+3)*pinch.span/Math.max(1,pointerSpan())-3);return}
  if(!drag||pinchUsed)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;
  if(walker.active){walker.yaw+=dx*.0035;walker.pitch=Math.max(-1.2,Math.min(1.2,walker.pitch-dy*.0035))}else{view.yaw+=dx*.0035;view.height=Math.max(-.45,Math.min(.9,view.height-dy*.0025))}drag={x:e.clientX,y:e.clientY};
});
function releaseCameraPointer(e){cameraPointers.delete(e.pointerId);drag=null;pinch=null;if(cameraPointers.size===0)pinchUsed=false}
for(const type of['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,releaseCameraPointer);
canvas.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey||walker.active||!running||pausedByRecord)return;e.preventDefault();setCameraDistance((cameraDistance+3)*Math.exp(Math.max(-200,Math.min(200,e.deltaY))*.0015)-3)},{passive:false});
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key,on=e=>{e.preventDefault();if(acrobatics.active||pausedByRecord)return;if(k==='s'&&requestAutoLanding())return;keys.add(k);try{b.setPointerCapture(e.pointerId)}catch{}},off=e=>{e.preventDefault();keys.delete(k)};b.addEventListener('pointerdown',on);['pointerup','pointercancel','lostpointercapture'].forEach(t=>b.addEventListener(t,off))});
const flightStick=$('#flightStick'),stickKnob=$('.stick-knob',flightStick);let stickPointer=null;
function moveStick(e){
  if(stickPointer!==e.pointerId)return;const rect=flightStick.getBoundingClientRect(),radius=rect.width*.34,dx=e.clientX-(rect.left+rect.width/2),dy=e.clientY-(rect.top+rect.height/2),distance=Math.hypot(dx,dy),scale=distance>radius?radius/distance:1,x=dx*scale/radius,y=dy*scale/radius,dead=.1;
  touchStick.roll=Math.abs(x)<dead?0:x;touchStick.pitch=Math.abs(y)<dead?0:-y;stickKnob.style.transform=`translate(calc(-50% + ${x*radius}px),calc(-50% + ${y*radius}px))`;
}
function releaseStick(e){if(stickPointer!==e.pointerId)return;stickPointer=null;touchStick.roll=0;touchStick.pitch=0;stickKnob.style.transform='translate(-50%,-50%)'}
flightStick.addEventListener('pointerdown',e=>{e.preventDefault();if(acrobatics.active||pausedByRecord)return;stickPointer=e.pointerId;flightStick.setPointerCapture(e.pointerId);flightStick.classList.add('active');moveStick(e)});
flightStick.addEventListener('pointermove',moveStick);['pointerup','pointercancel','lostpointercapture'].forEach(t=>flightStick.addEventListener(t,e=>{flightStick.classList.remove('active');releaseStick(e)}));
$('#openJournal').addEventListener('click',openJournal);$('#closeJournal').addEventListener('click',closeJournal);$('#journalDialog .close').addEventListener('click',closeJournal);$('#journalDialog').addEventListener('close',()=>{clearMovement();pausedByRecord=false;});
$('#lookFromClue').addEventListener('click',()=>{if(!clueLookTarget||!walker.active)return;const target=clueLookTarget;closeRecord();walker.yaw=Math.atan2(target.x-walker.x,target.z-walker.z);walker.pitch=Math.atan2(terrainHeight(target.x,target.z)+125-walker.y,Math.hypot(target.x-walker.x,target.z-walker.z));});
$('#investigate').addEventListener('click',investigate);$('#continueFlight').addEventListener('click',closeRecord);$('#recordDialog .close').addEventListener('click',closeRecord);$('#recordDialog').addEventListener('close',()=>{pausedByRecord=false});
radar.addEventListener('pointerdown',e=>e.preventDefault());radar.addEventListener('pointerup',jumpToRadarPoint);
$('#toggleDesign').addEventListener('click',e=>{design=!design;e.currentTarget.classList.toggle('active',design);e.currentTarget.textContent=`設計線 ${design?'ON':'OFF'}`});$('#toggleMapJump').addEventListener('click',e=>{mapJumpEnabled=!mapJumpEnabled;e.currentTarget.classList.toggle('active',mapJumpEnabled);e.currentTarget.setAttribute('aria-pressed',String(mapJumpEnabled));e.currentTarget.textContent=`座標跳躍 ${mapJumpEnabled?'ON':'OFF'}`;radar.classList.toggle('jump-enabled',mapJumpEnabled);radar.title=mapJumpEnabled?'タップした座標へ瞬間移動':'飛行記憶マップ';persist()});$('#openConcept').addEventListener('click',()=>$('#conceptDialog').showModal());$('#conceptDialog .close').addEventListener('click',()=>$('#conceptDialog').close());$('#enterBlockout').addEventListener('click',()=>{ensureAmbience();try{audioContext?.resume()}catch{}$('#briefDialog').close();running=true;canvas.focus()});
$('#toggleMapJump').classList.toggle('active',mapJumpEnabled);$('#toggleMapJump').setAttribute('aria-pressed',String(mapJumpEnabled));$('#toggleMapJump').textContent=`座標跳躍 ${mapJumpEnabled?'ON':'OFF'}`;radar.classList.toggle('jump-enabled',mapJumpEnabled);
updateHud();$('#briefDialog').showModal();requestAnimationFrame(loop);

const cameraButton=$('#toggleCamera'),distanceSlider=$('#cameraDistance');
function cameraLabel(){
  cameraButton.disabled=walker.active;distanceSlider.disabled=walker.active;
  if(walker.active){cameraButton.textContent='視点：地上';$('#cameraDistanceLabel').textContent='地上では固定';return}
  cameraButton.textContent=cameraMode==='rider'?'視点：一人称':'視点：後方';cameraButton.setAttribute('aria-pressed',String(cameraMode==='rider'));
  distanceSlider.value=String(cameraDistanceToSlider(cameraDistance));const label=cameraMode==='rider'?'一人称':(cameraDistance<10?cameraDistance.toFixed(1):Math.round(cameraDistance))+' m';$('#cameraDistanceLabel').textContent=label;distanceSlider.setAttribute('aria-valuetext',label);
}
distanceSlider.addEventListener('input',e=>setCameraDistance(sliderToCameraDistance(e.currentTarget.value)));
cameraButton.addEventListener('click',()=>{if(walker.active)return;if(!webglDragon?.ready){$('.reaction p').textContent='一人称視点には3D描画が必要です。';return}view.yaw=0;view.height=0;setCameraDistance(cameraMode==='rider'?lastChaseDistance:0)});cameraLabel();snapCamera();

function clearMovement(){clearCameraGesture();keys.clear();touchStick.roll=0;touchStick.pitch=0;drag=null;stickPointer=null;stickKnob.style.transform='translate(-50%,-50%)';flightStick.classList.remove('active')}
function toggleGroundWalk(){
  if(!running||pausedByRecord||landing.phase!=='landed')return;
  if(walker.active&&!canMountDragon(walker,flight))return;
  if(walker.active){walker.active=false;view.yaw=0;view.height=0}else Object.assign(walker,dismountPose(flight,terrainHeight));
  clearMovement();document.body.classList.toggle('on-foot',walker.active);snapCamera();cameraLabel();updateGroundUI();
}
function updateGroundUI(){
  $('#nearPrompt').hidden=true;
  const visible=running&&landing.phase==='landed'&&!pausedByRecord;
  document.body.classList.toggle('ground-ready',visible);$('#groundAction').hidden=!visible;const mountable=canMountDragon(walker,flight);$('#toggleGroundWalk').disabled=!mountable;$('#toggleGroundWalk').textContent=walker.active?(mountable?'ドラゴンに乗る':`相棒まで ${Math.ceil(distance2d(walker,flight))} m`):'地面に降りる';
  $('#groundHint').hidden=!walker.active;flightStick.querySelector('small').textContent=walker.active?'歩く':'旋回・機首';flightStick.setAttribute('aria-label',walker.active?'上下で前進・後退、左右で横移動':'操縦桿。左右で旋回、上下で機首を上げ下げ');
  if(walker.active){$('.touch-boost').textContent='前進';$('.touch-brake').textContent='後退';$('.reaction p').textContent='相棒の周囲を歩ける。画面をドラッグして見回そう。';$('#nearPrompt').hidden=true;$('#flightState').textContent='徒歩';const site=activeStorySite();if(site){const p=nearestStoryPoint(walker,site);$('#groundHint').textContent=distance2d(walker,site.center)>site.radiusM-13?'この先は崩れた斜面だ。足場へ戻ろう。':'左スティック・WASDで歩く。ドラッグで見回す。相棒の近くで乗る。';$('#nearPrompt').hidden=!p||!running||pausedByRecord;if(p){$('span',$('#nearPrompt')).textContent=(p.recordIds.length?p.recordIds.every(id=>collected.has(id)):observed.has(p.id))?'見つけた痕跡':'手の届くところに痕跡がある';$('strong',$('#nearPrompt')).textContent=p.label;$('#investigate').textContent=!p.recordIds.length?'調べる':p.recordIds.every(id=>collected.has(id))?'読み直す':'読む';}}else $('#groundHint').textContent='WASD・左スティックで歩く　ドラッグ・矢印で見回す　Gで乗る';}else $('span',$('#nearPrompt')).textContent='ドラゴンが痕跡を見つけた';
  $('.touch-boost').setAttribute('aria-label',walker.active?'前進':$('.touch-boost').textContent);$('.touch-brake').setAttribute('aria-label',walker.active?'後退':$('.touch-brake').textContent);
}
$('#toggleGroundWalk').addEventListener('click',toggleGroundWalk);
addEventListener('blur',clearMovement);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearMovement()});

$('#rollAction').addEventListener('click',()=>requestRoll('roll'));$('#loopAction').addEventListener('click',()=>requestRoll('loop'));

$('#dashAction').addEventListener('click',()=>requestRoll('dash'));

$('#fallAction').addEventListener('click',()=>requestRoll('fall'));


$('#turnAction').addEventListener('click',()=>requestRoll('turn'));

function closeControlMenus(){acrobatics.menuOpen=false;$('#settingsPanel').hidden=true;$('#toggleSettings').setAttribute('aria-expanded','false');updateRollUI()}
$('#toggleSkills').addEventListener('click',()=>{if(acrobatics.active)return;acrobatics.menuOpen=!acrobatics.menuOpen;clearMovement();$('#settingsPanel').hidden=true;$('#toggleSettings').setAttribute('aria-expanded','false');updateRollUI()});
$('#closeSkills').addEventListener('click',()=>{acrobatics.menuOpen=false;updateRollUI();$('#toggleSkills').focus()});
$('#toggleSettings').addEventListener('click',()=>{const panel=$('#settingsPanel');panel.hidden=!panel.hidden;$('#toggleSettings').setAttribute('aria-expanded',String(!panel.hidden));acrobatics.menuOpen=false;clearMovement();updateRollUI()});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#acroControls,#toggleSkills,#settingsPanel,#toggleSettings'))closeControlMenus()});
// Native callouts and selection are blocked on controls, while story text remains selectable.
for(const control of document.querySelectorAll('.touch-controls,#acroControls,#toggleSkills,.topbar,.ground-action,.near-prompt,#scene,#radar')){
  control.addEventListener('contextmenu',e=>e.preventDefault());control.addEventListener('selectstart',e=>e.preventDefault());control.addEventListener('dragstart',e=>e.preventDefault());
}
addEventListener('resize',()=>{clearMovement();closeControlMenus()});
addEventListener('blur',closeControlMenus);

$('#toggleFlightDetails').addEventListener('click',()=>{const enabled=$('#toggleFlightDetails').getAttribute('aria-pressed')!=='true';document.body.classList.toggle('hud-details',enabled);$('#toggleFlightDetails').setAttribute('aria-pressed',String(enabled));$('#toggleFlightDetails').textContent=enabled?'飛行情報：詳細':'飛行情報：簡易'});
$('#toggleNarration').addEventListener('click',()=>{const enabled=$('#toggleNarration').getAttribute('aria-pressed')!=='true';document.body.classList.toggle('show-narration',enabled);$('#toggleNarration').setAttribute('aria-pressed',String(enabled));$('#toggleNarration').textContent=enabled?'相棒の声：表示':'相棒の声：非表示'});
